<?php
declare(strict_types=1);
require_once __DIR__.'/operations.php';
header('Content-Type: application/json; charset=utf-8');
function limited_error_json(array $body,int $status=200):void{http_response_code($status);echo json_encode($body,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);exit;}
try{
    require_role('owner_admin','front_desk_admin','front_desk_admin_employee');
    if($_SERVER['REQUEST_METHOD']!=='POST')limited_error_json(['ok'=>false,'success'=>false,'error'=>'Method not allowed.'],405);
