    $allowed=['csrf','error_id','occurred_on','financial_impact'];$restricted=array_diff(array_keys($payload),$allowed);if($restricted)limited_error_json(['ok'=>false,'success'=>false,'error'=>'You do not have permission to update those error fields.'],403);
    $csrf=(string)($payload['csrf']??'');$expected=(string)($_SESSION['error_limited_edit_csrf']??'');if($csrf===''||$expected===''||!hash_equals($expected,$csrf))limited_error_json(['ok'=>false,'success'=>false,'error'=>'Your session expired. Refresh and try again.'],403);
    $errorId=max(0,(int)($payload['error_id']??0));$actorEmployee=(int)(ops_current_employee_id()??0);$visibilitySql='id=? AND deleted_at IS NULL';$visibilityParams=[$errorId];if(!user_has_role('owner_admin')){$visibilitySql.=' AND (employee_id=? OR people_involved LIKE ? OR people_involved LIKE ? OR people_involved LIKE ? OR people_involved LIKE ? OR logged_by=? OR EXISTS (SELECT 1 FROM ops_error_instruction_reads instruction_read JOIN ops_error_instructions instruction ON instruction.id=instruction_read.instruction_id WHERE instruction.error_id=ops_error_logs.id AND instruction_read.recipient_user_id=?))';array_push($visibilityParams,$actorEmployee,'['.$actorEmployee.']','['.$actorEmployee.',%','%,'.$actorEmployee.',%','%,'.$actorEmployee.']',$actorEmployee,$actorEmployee);}$rows=ops_rows("SELECT * FROM ops_error_logs WHERE {$visibilitySql} LIMIT 1",$visibilityParams);if(!$rows)limited_error_json(['ok'=>false,'success'=>false,'error'=>'Error record not found.'],404);$existing=$rows[0];
    $zone=new DateTimeZone('Africa/Windhoek');$rawDate=trim((string)($payload['occurred_on']??''));$date=DateTimeImmutable::createFromFormat('!Y-m-d',$rawDate,$zone);$dateErrors=DateTimeImmutable::getLastErrors();if(!$date||(is_array($dateErrors)&&(($dateErrors['warning_count']??0)||($dateErrors['error_count']??0)))||$date->format('Y-m-d')!==$rawDate)limited_error_json(['ok'=>false,'success'=>false,'error'=>'Please select a valid error date.'],422);if($date>new DateTimeImmutable('today',$zone))limited_error_json(['ok'=>false,'success'=>false,'error'=>'The error date cannot be in the future.'],422);
